-性癖: 开场白不涉及性癖提取！
指令: 检测到冷启动状态。忽略所有变量的 check 限制，强制执行全量覆写 (Operation: replace)，将所有变量的当前值写入 JSON Patch，以完成数据实例化。
]`;
try{
if(typeof triggerSlash==='function'){triggerSlash(`/send ${txt.replace(/\n/g,' ')} | /trigger`);}
else if(typeof send_text_to_input==='function'){send_text_to_input(txt,true);setTimeout(()=>{const b=document.getElementById('send_textarea');if(b)b.click()},200);}
else{navigator.clipboard.writeText(txt).then(()=>alert("指令已复制"));}
const b=document.getElementById('btn');b.innerText="已开拍";b.disabled=true;
}catch(e){alert("错误");console.error(e);}
}
