<div id="fate-ui-root" data-fate-marker="1"></div>
<script>
function esc(s){
if(!s)return'';
return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function getMsg(){
var c=getChatMessages(getCurrentMessageId());
if(!c||c.length===0)return null;
return c[0].message;
}
function getMyIndex(){
try{
var me=window.frameElement;
if(!me)return 0;
var container=me.closest('.mes_text');
if(!container)container=me.parentElement;
var allFrames=container.querySelectorAll('iframe');
var idx=0;
for(var i=0;i<allFrames.length;i++){
var f=allFrames[i];
if(f===me)return idx;
try{if(f.contentDocument&&f.contentDocument.querySelector('[data-fate-marker]'))idx++;}catch(e){}
}
return 0;
}catch(e){return 0;}
}
function extractBlock(msg,idx){
msg=msg.replace(/<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi,'');
msg=msg.replace(/^[\s\S]*?<\/think(?:ing)?>/i,'');
var re=/<fate_ui>([\s\S]*?)<\/fate_ui>/g;
var m,i=0;
while((m=re.exec(msg))!==null){
if(i===idx)return m[1].trim();
i++;
}
return null;
}
function getType(block){
var m=block.match(/:::\s*(\w+)/);
return m?m[1]:'';
}
function pf(c,n){
var r=new RegExp('\\['+n.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\|([\\s\\S]*?)\\](?=\\s*(?:\\n\\s*(?:\\[|{|:::)|$))');
var m=c.match(r);
return m?m[1].trim():'';
}
function parseItems(c,pfx){
var items=[];
var r=new RegExp('{'+pfx.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\|([\\s\\S]*?)}(?=\\s*(?:\\n\\s*(?:\\[|{|:::)|$))','g');
var m;
while((m=r.exec(c))!==null){
items.push(m[1].split('|'));
}return items;}
function parseAmt(s){
if(!s)return 0;s=s.replace(/[,，\s]/g,'');
if(s.indexOf('亿')>=0)return parseFloat(s)*100000000;
if(s.indexOf('万')>=0)return parseFloat(s)*10000;
return parseFloat(s)||0;}
function fmtMoney(s){
if(!s)return s;
s=s.toString().trim().replace(/[,，\s]/g,'');
if(/[亿万元百千]/.test(s))return s;
var n=parseFloat(s);
if(isNaN(n))return s;
if(n>=100000000){var yi=n/100000000;return(Number.isInteger(yi)?yi:parseFloat(yi.toFixed(2)))+'亿';}
if(n>=10000){var wan=n/10000;return(Number.isInteger(wan)?wan:parseFloat(wan.toFixed(2)))+'万';}
return n+'元';}
function fmtNum(s){
if(!s)return s;
s=s.toString().trim().replace(/[,，\s]/g,'');
var n=parseFloat(s);
if(isNaN(n))return s;
if(n>=100000000)return parseFloat((n/100000000).toFixed(1))+'亿';
if(n>=10000)return parseFloat((n/10000).toFixed(1))+'万';
return n.toString();
}
function mkStars(score){
var s=parseFloat(score)||0;var full=Math.round(s/2);if(full>5)full=5;if(full<0)full=0;
var h='';for(var i=0;i<5;i++)h+='<span class="rv-star'+(i<full?' on':'')+'">★</span>';return h;}
function getPfCls(p){
if(!p)return'douban';var l=p.toLowerCase();
if(l.indexOf('imdb')>=0)return'imdb';
if(l.indexOf('烂番茄')>=0||l.indexOf('tomato')>=0)return'tomato';
return'douban';}
function getMpCls(p){
if(!p)return'mp-ne';var l=p.toLowerCase();
if(l.indexOf('qq')>=0)return'mp-qq';
if(l.indexOf('酷狗')>=0||l.indexOf('kugou')>=0)return'mp-kg';
return'mp-ne';
}
function rSms(c){
var ct=pf(c,'联系人')||'未知';
var msgs=[];
var re=/{(收|发)\|([\s\S]*?)}(?=\s*(?:\n\s*(?:[\[{]|:::)|$))/g;
var m;
while((m=re.exec(c))!==null){
msgs.push({d:m[1]==='收'?'r':'s', t:m[2].trim()});
}
var h='<div class="sms-wrap"><div class="sms-hdr">'+esc(ct)+'</div><div class="sms-body">';
for(var i=0;i<msgs.length;i++){
var txt = esc(msgs[i].t).replace(/\n/g, '<br>');
h+='<div class="sms-b sms-'+msgs[i].d+'">'+txt+'</div>';
}
return h+'</div></div>';}
function rWechat(c){
var ct=pf(c,'联系人')||'未知';
var msgs=[];
var re=/{(收|发)\|([\s\S]*?)}(?=\s*(?:\n\s*(?:[\[{]|:::)|$))/g;
var m;
while((m=re.exec(c))!==null){
var type=m[1], inner=m[2].trim();
if(type==='收'){
var fp=inner.indexOf('|');
var sender=fp>=0?inner.substring(0,fp):'';
var txt=fp>=0?inner.substring(fp+1):inner;
msgs.push({d:'r', s:sender, t:txt});
}else{
msgs.push({d:'s', s:'', t:inner});
}
}
var h='<div class="wx-wrap"><div class="wx-hdr">'+esc(ct)+'</div><div class="wx-body">';
for(var i=0;i<msgs.length;i++){
var mg=msgs[i];
var txt = esc(mg.t).replace(/\n/g, '<br>');
if(mg.d==='r'){
h+='<div class="wx-row wr">';
if(mg.s)h+='<span class="wx-sn">'+esc(mg.s)+'</span>';
h+='<div class="wx-b">'+txt+'</div></div>';
}else{
h+='<div class="wx-row ws"><div class="wx-b">'+txt+'</div></div>';
}
}
return h+'</div></div>';}
function rQq(c){
var ct=pf(c,'联系人')||'未知';
var msgs=[];
var re=/{(收|发)\|([\s\S]*?)}(?=\s*(?:\n\s*(?:[\[{]|:::)|$))/g;
var m;
while((m=re.exec(c))!==null){
var type=m[1],inner=m[2].trim();
if(type==='收'){
var fp=inner.indexOf('|');
var sender=fp>=0?inner.substring(0,fp):'';
var txt=fp>=0?inner.substring(fp+1):inner;
msgs.push({d:'r',s:sender,t:txt});
}else{
msgs.push({d:'s',s:'',t:inner});
}
}
var h='<div class="qq-wrap"><div class="qq-hdr">'+esc(ct)+'</div><div class="qq-body">';
for(var i=0;i<msgs.length;i++){
var mg=msgs[i];
var txt=esc(mg.t).replace(/\n/g,'<br>');
if(mg.d==='r'){
h+='<div class="qq-row qr">';
if(mg.s)h+='<span class="qq-sn">'+esc(mg.s)+'</span>';
h+='<div class="qq-b">'+txt+'</div></div>';
}else{
h+='<div class="qq-row qs"><div class="qq-b">'+txt+'</div></div>';
}
}
return h+'</div></div>';}
function rCall(c){
var ct=pf(c,'联系人')||'未知';var st=pf(c,'状态')||'来电';var dur=pf(c,'时长');
var ini=ct.charAt(0);
