function rMoments(c){
var un=pf(c,'用户名')||'用户',ct=pf(c,'内容'),img=pf(c,'附图'),loc=pf(c,'位置'),tm=pf(c,'时间'),likes=pf(c,'赞');
var ini=un.charAt(0);
var h='<div class="mm"><div class="mm-hdr"><div class="mm-av">'+esc(ini)+'</div><div class="mm-ui"><div class="mm-nm">'+esc(un)+'</div></div></div>';
if(ct){var mct=esc(ct).replace(/\n/g,'<br>');h+='<div class="mm-ct">'+mct+'</div>';}
if(img)h+='<div class="mm-img">📷 '+esc(img)+'</div>';
if(loc)h+='<div class="mm-loc">📍 '+esc(loc)+'</div>';
if(tm)h+='<div class="mm-time">'+esc(tm)+'</div>';
var si=[];
var sr=/{(评|回)\|([\s\S]*?)}(?=\s*(?:\n\s*(?:[\[{]|:::)|$))/g;
var sm;
