<body>
    <div id="app"><div class="loading">正在加载小组数据...</div></div>

    <script>
        var globalPosts = [];

        function getAvatarColor(str) {
            var colors = ['#e74c3c','#e67e22','#f39c12','#2ecc71','#1abc9c','#3498db','#9b59b6','#e91e63','#00897b','#5c6bc0'];
            var hash = 0;
            for (var i = 0; i < str.length; i++) hash = str.charCodeAt(i) + ((hash << 5) - hash);
            return colors[Math.abs(hash) % colors.length];
        }

        function extractField(text, fieldName) {
            var regex = new RegExp('\\[' + fieldName + '\\|([^\\]]+)\\]');
            var match = text.match(regex);
            return match ? match[1].trim() : '';
        }

        function extractBlock(text, blockName) {
            var regex = new RegExp('<' + blockName + '>([\\s\\S]*?)<\\/' + blockName + '>');
            var match = text.match(regex);
            return match ? match[1] : '';
        }

        function getTagClass(section) {
            var map = { '粉丝安利': 'post-tag-fans', '路人讨论': 'post-tag-passerby', '八卦爆料': 'post-tag-gossip', '作品分析': 'post-tag-review' };
            return map[section] || 'post-tag-passerby';
        }

        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) return null;
            return chatMessages[0].message;
        }

        function parseData(messageText) {
            messageText=messageText.replace(/<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi,'');
            messageText=messageText.replace(/^[\s\S]*?<\/think(?:ing)?>/i,'');
            var mainMatch = messageText.match(/<star_zone>([\s\S]*?)<\/star_zone>/);
            if (!mainMatch) return null;
            var raw = mainMatch[1];

            var data = { info: {}, posts: [] };

            var infoBlock = extractBlock(raw, 'zone_info');
            data.info.name = extractField(infoBlock, '小组名');
            data.info.desc = extractField(infoBlock, '简介');
            data.info.members = extractField(infoBlock, '成员');
            data.info.total = extractField(infoBlock, '帖子总数');

            var postsBlock = extractBlock(raw, 'post_list');
            var postChunks = postsBlock.split('<post>');

            for (var i = 1; i < postChunks.length; i++) {
                var chunk = postChunks[i].split('</post>')[0];
                if (!chunk.trim()) continue;

                var section = extractField(chunk, '板块');
                var title = extractField(chunk, '标题');

                if (!section || !title) continue;

                var post = {
                    id: data.posts.length,
                    section: section,
                    title: title,
                    author: extractField(chunk, '作者'),
                    time: extractField(chunk, '时间'),
                    body: extractField(chunk, '正文'),
                    replyCount: extractField(chunk, '回复数'),
                    favCount: extractField(chunk, '收藏数'),
                    replies: []
                };

                var replyMatches = chunk.match(/{回\|([^}]+)}/g);
                if (replyMatches) {
                    for (var j = 0; j < replyMatches.length; j++) {
                        var rMatch = replyMatches[j].match(/{回\|([^}]+)}/);
                        if (rMatch && rMatch[1]) {
                            var parts = rMatch[1].split('|');
                            if (parts.length >= 2 && parts[0].trim() && parts[1].trim()) {
                                post.replies.push({
                                    user: parts[0].trim(),
                                    text: parts[1].trim(),
                                    likes: parseInt(parts[2]) || 0
                                });
                            }
                        }
                    }
                }

                data.posts.push(post);
            }

            return data;
        }

        function renderPage(data) {
            globalPosts = data.posts;

            var sectionSet = {};
            data.posts.forEach(function(p) {
                if (p.section) sectionSet[p.section] = true;
            });
            var sections = Object.keys(sectionSet);

            var tabsHtml = '<div class="zone-tab active" onclick="filterSection.call(this,\'全部\')">全部</div>';
            for (var i = 0; i < sections.length; i++) {
                tabsHtml += '<div class="zone-tab" onclick="filterSection.call(this,\'' + sections[i] + '\')">' + sections[i] + '</div>';
            }

            var nameInitial = (data.info.name || '组').charAt(0);

            var html = '<div class="zone-wrapper" id="zone-wrapper">' +
                '<div class="zone-view" id="zone-main">' +
                    '<div class="zone-header">' +
                        '<div class="zone-icon">' + nameInitial + '</div>' +
                        '<div class="zone-name">' + (data.info.name || '话题讨论组') + '</div>' +
                        (data.info.desc ? '<div class="zone-desc">' + data.info.desc + '</div>' : '') +
                        '<div class="zone-stats">' +
                            '<span><strong>' + (data.info.members || '0') + '</strong> 成员</span>' +
                            '<span><strong>' + (data.info.total || '0') + '</strong> 帖子</span>' +
                        '</div>' +
                    '</div>' +
                    '<div class="zone-tabs">' + tabsHtml + '</div>' +
                    '<div class="post-list" id="post-list"></div>' +
                '</div>' +
                '<div class="zone-view" id="zone-detail"></div>' +
            '</div>';

            document.getElementById('app').innerHTML = html;
            buildPostList('全部');
        }

        function buildPostList(section) {
            var filtered = (section === '全部') ? globalPosts : globalPosts.filter(function(p) { return p.section === section; });

            if (filtered.length === 0) {
                document.getElementById('post-list').innerHTML = '<div class="empty-state">这个板块还没有帖子</div>';
                return;
            }

            var html = '';
            for (var i = 0; i < filtered.length; i++) {
                var post = filtered[i];
                var preview = post.body.length > 80 ? post.body.substring(0, 80) + '...' : post.body;
                var tagCls = getTagClass(post.section);

                html += '<div class="post-item" onclick="openPost(' + post.id + ')">' +
                    '<div class="post-title"><span class="post-tag ' + tagCls + '">' + post.section + '</span>' + post.title + '</div>' +
                    '<div class="post-preview">' + preview + '</div>' +
                    '<div class="post-meta">' +
                        '<span class="post-author">' + post.author + '</span>' +
                        '<span>' + post.time + '</span>' +
                        '<span class="post-replies">' + post.replyCount + '回复</span>' +
                    '</div>' +
                '</div>';
            }

            document.getElementById('post-list').innerHTML = html;
        }

        window.filterSection = function(section) {
            var tabs = document.querySelectorAll('.zone-tab');
            for (var i = 0; i < tabs.length; i++) { tabs[i].classList.remove('active'); }
            this.classList.add('active');
            buildPostList(section);
        };

        window.openPost = function(postId) {
            var post = null;
            for (var i = 0; i < globalPosts.length; i++) {
                if (globalPosts[i].id === postId) { post = globalPosts[i]; break; }
            }
            if (!post) return;

            var repliesHtml = '';
            if (post.replies.length > 0) {
                for (var j = 0; j < post.replies.length; j++) {
                    var r = post.replies[j];
                    var letter = r.user.charAt(0);
                    var bg = getAvatarColor(r.user);
                    repliesHtml += '<div class="reply-item">' +
                        '<div class="reply-avatar" style="background:' + bg + '">' + letter + '</div>' +
                        '<div class="reply-body">' +
                            '<div class="reply-user">' + r.user + '</div>' +
                            '<div class="reply-text">' + r.text + '</div>' +
                            (r.likes > 0 ? '<div class="reply-bottom"><span></span><span class="reply-likes">👍 ' + r.likes + '</span></div>' : '') +
                        '</div>' +
                    '</div>';
                }
            }

            var bodyHtml = post.body.replace(/\\n/g, '<br>').replace(/\n/g, '<br>');

            var detailHtml = '<div class="detail-header">' +
                '<div class="detail-back" onclick="closePost()">‹</div>' +
                '<div class="detail-nav-title">' + post.section + '</div>' +
            '</div>' +
            '<div class="detail-body">' +
                '<div class="detail-title">' + post.title + '</div>' +
                '<div class="detail-info">' +
                    '<span class="detail-author-name">' + post.author + '</span>' +
                    '<span class="detail-time">' + post.time + '</span>' +
                    '<span class="detail-fav">♡ ' + post.favCount + ' 收藏</span>' +
                '</div>' +
                '<div class="detail-text">' + bodyHtml + '</div>' +
                (post.replies.length > 0 ?
                    '<div class="reply-section">' +
                        '<div class="reply-header">回应 (' + post.replyCount + ')</div>' +
                        repliesHtml +
                    '</div>' : '') +
            '</div>';

            var wrapper = document.getElementById('zone-wrapper');
            var detail = document.getElementById('zone-detail');
            detail.innerHTML = detailHtml;

            setTimeout(function() {
                var detailHeight = detail.scrollHeight;
                var mainHeight = document.getElementById('zone-main').scrollHeight;
                var needed = Math.max(detailHeight, mainHeight);
                if (needed > wrapper.offsetHeight) {
                    wrapper.style.minHeight = needed + 'px';
                }
            }, 10);

            wrapper.classList.add('show-detail');
        };

        window.closePost = function() {
            var wrapper = document.getElementById('zone-wrapper');
            wrapper.classList.remove('show-detail');
            wrapper.style.minHeight = '';
            setTimeout(function() {
                document.getElementById('zone-detail').innerHTML = '';
            }, 300);
        };

        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('app').innerHTML = '<div class="loading">❌ 无法获取消息数据</div>';
                    return;
                }
                var data = parseData(messageText);
                if (!data) {
                    document.getElementById('app').innerHTML = '<div class="loading">❌ 未找到小组数据标签</div>';
                    return;
                }
                renderPage(data);
            } catch (error) {
                console.error(error);
                document.getElementById('app').innerHTML = '<div class="loading">❌ 渲染失败：' + error.message + '</div>';
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>
