    <script>
        function esc(s){
            if(!s)return'';
            return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
        }

        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                return null;
            }
            return chatMessages[0].message;
        }

        function getMyIndex(){
            try{
                var me=window.frameElement;
                if(!me)return 0;
                var container=me.closest('.mes_text');
                if(!container)container=me.parentElement;
                var allFrames=container.querySelectorAll('iframe');
                var idx=0;
                for(var i=0;i<allFrames.length;i++){
                    var f=allFrames[i];
                    if(f===me)return idx;
                    try{if(f.contentDocument&&f.contentDocument.querySelector('[data-consent-marker]'))idx++;}catch(e){}
                }
                return 0;
            }catch(e){return 0;}
        }

        function parseData(messageText, idx) {
            var result = {};
            messageText=messageText.replace(/<think(?:ing)?>[\s\S]*?<\/think(?:ing)?>/gi,'');
            messageText=messageText.replace(/^[\s\S]*?<\/think(?:ing)?>/i,'');
            var re=/<av_consent_form>([\s\S]*?)<\/av_consent_form>/g;
            var m, i=0;
            var content=null;
            while((m=re.exec(messageText))!==null){
                if(i===idx){content=m[1];break;}
                i++;
            }
            if(!content)return result;
            var regex = /\[(.*?)\|([\s\S]*?)\]/g;
            var match;
            while ((match = regex.exec(content)) !== null) {
                var key = match[1].trim();
                var value = match[2].trim();
                result[key] = value;
            }
            return result;
        }

        function makeRow(label, value) {
            return '<div class="info-row">' +
                '<div class="info-label">' + label + '</div>' +
                '<div class="info-separator">：</div>' +
                '<div class="info-value">' + esc(value || '未記載') + '</div>' +
            '</div>';
        }

        function renderPage(data) {
            var partyA = data['甲方'] || '';
            var partyB = data['乙方'] || '';
            var shootDate = data['拍摄日'] || '';
            var fee = data['片酬'] || '';
            var planContent = data['企划内容'] || '';
            var isPostLaw = !!data['签约日'];
            var html = '';
            if (isPostLaw) {
                html += '<div class="header">' +
                    '<div class="title">出演承諾書 (同意書)</div>' +
                    '<div class="subtitle">AV出演被害防止・救済法に基づく書面</div>' +
                '</div>';
            } else {
                html += '<div class="header">' +
                    '<div class="title">出演承諾書</div>' +
                    '<div class="subtitle">撮影内容確認書面</div>' +
                '</div>';
            }
            html += '<div class="info-group">' +
                makeRow('甲（制作会社）', partyA) +
                makeRow('乙（実演者）', partyB) +
            '</div>';
            html += '<div class="info-group">';

            if (isPostLaw) {
                html += makeRow('契約締結日', data['签约日'] || '');
                html += makeRow('撮影予定日', shootDate);
                html += makeRow('公開予定日', data['发售日'] || '');
            } else {
                html += makeRow('撮影予定日', shootDate);
            }

            html += makeRow('出演料（報酬）', fee);
            html += '</div>';
            html += '<div class="content-box">' +
                '<div class="content-title">【撮影内容及び許容範囲】</div>' +
                '<div class="content-text">' + esc(planContent || '未記載') + '</div>' +
            '</div>';
            if (isPostLaw) {
                html += '<div class="legal-warning">' +
                    '※ 契約締結日から1ヶ月間は撮影を行うことができません（熟慮期間）。<br>' +
                    '※ 公開日から1年間は無条件で販売停止を求める権利を有します。' +
                '</div>';
            }
            html += '<div class="stamp-area">' +
                '<div class="stamp-box">' + (isPostLaw ? '確認済' : '承諾') + '</div>' +
            '</div>';

            document.getElementById('render-target').innerHTML = html;
        }

        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById('render-target').innerHTML = '<div class="loading">❌ メッセージの取得に失敗しました</div>';
                    return;
                }
                var idx = getMyIndex();
                var data = parseData(messageText, idx);
                renderPage(data);
            } catch (error) {
                document.getElementById('render-target').innerHTML = '<div class="loading">❌ エラー：' + error.message + '</div>';
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>
