function parseItems(c,pfx){
var items=[];
var r=new RegExp('{'+pfx.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\|([\\s\\S]*?)}(?=\\s*(?:\\n\\s*(?:\\[|{|:::)|$))','g');
var m;
while((m=r.exec(c))!==null){
items.push(m[1].split('|'));
}return items;
}
function parseMixed(c){
var items=[];
var r=/{(弹|礼|系|商)\|([\s\S]*?)}(?=\s*(?:\n\s*(?:[\[{]|:::)|$))/g;
var m;
while((m=r.exec(c))!==null){
items.push({type:m[1],data:m[2].split('|')});
}
return items;
}
function fmtNum(s){
if(!s)return s;
s=s.toString().trim().replace(/[,，\s]/g,'');
var n=parseFloat(s);
if(isNaN(n))return s;
if(n>=100000000)return parseFloat((n/100000000).toFixed(1))+'亿';
if(n>=10000)return parseFloat((n/10000).toFixed(1))+'万';
return n.toString();
}
function fmtMoney(s){
if(!s)return s;
s=s.toString().trim().replace(/[,，\s]/g,'');
if(/[亿万元百千]/.test(s))return s;
var n=parseFloat(s);
if(isNaN(n))return s;
if(n>=100000000){var yi=n/100000000;return(Number.isInteger(yi)?yi:parseFloat(yi.toFixed(2)))+'亿';}
if(n>=10000){var wan=n/10000;return(Number.isInteger(wan)?wan:parseFloat(wan.toFixed(2)))+'万';}
return n+'元';
}
function getSvCls(p){
if(!p)return'sv-dy';
var l=p.toLowerCase();
if(l.indexOf('快手')>=0)return'sv-ks';
if(l.indexOf('b站')>=0||l.indexOf('bili')>=0||l.indexOf('哔哩')>=0)return'sv-bili';
if(l.indexOf('小红书')>=0)return'sv-xhs';
if(l.indexOf('视频号')>=0||l.indexOf('微信')>=0)return'sv-wxv';
return'sv-dy';
}
function rLiveStream(c){
var mn=pf(c,'主播')||'主播';
var pfm=pf(c,'平台')||'';
var ol=pf(c,'在线')||'0';
var lk=pf(c,'点赞')||'0';
var dur=pf(c,'时长')||'';
var msgs=parseMixed(c);
var h='<div class="ls"><div class="ls-hdr"><div class="ls-left"><span class="ls-live"></span><span class="ls-mn">'+esc(mn)+'</span>';
if(pfm)h+='<span class="ls-pf">'+esc(pfm)+'</span>';
h+='</div><div class="ls-stat">';
h+='<span class="ls-ol">👤 <span class="ls-ol-num">'+fmtNum(ol)+'</span></span>';
h+='<span class="ls-lk">♡ '+fmtNum(lk)+'</span>';
if(dur)h+='<span class="ls-lk">'+esc(dur)+'</span>';
h+='</div></div><div class="ls-bd">';
for(var i=0;i<msgs.length;i++){
var it=msgs[i];
if(it.type==='弹'){
h+='<div class="ls-dm"><span class="ls-nk">'+esc(it.data[0]||'')+'</span><span class="ls-tx">'+esc(it.data[1]||'')+'</span></div>';
}else if(it.type==='礼'){
h+='<div class="ls-gi"><span class="ls-gi-ico">🎁</span><span class="ls-nk">'+esc(it.data[0]||'')+'</span><span class="ls-tx">送出</span><span class="ls-gn">'+esc(it.data[1]||'')+'</span><span class="ls-gq">×'+esc(it.data[2]||'1')+'</span></div>';
}else if(it.type==='系'){
h+='<div class="ls-si">'+esc(it.data[0]||'')+'</div>';
}else if(it.type==='商'){
