if(it.data[1])h+='<div class="ls-pdp">¥'+esc(it.data[1])+'</div>';
if(it.data[2])h+='<div class="ls-pds">已售 '+esc(it.data[2])+'</div>';
h+='</div><span class="ls-pdb">去购买</span></div>';
}
}
h+='</div></div>';
return h;
}
function rShortVideo(c){
var pfm=pf(c,'平台')||'抖音';
var un=pf(c,'用户名')||'';
var cert=pf(c,'认证')||'';
var desc=pf(c,'描述')||'';
