var fans=pf(c,'新增粉丝');
var tips=pf(c,'打赏总额');
var gmv=pf(c,'GMV');
var avg=pf(c,'客单价');
var ret=pf(c,'退货率');
var comm=pf(c,'佣金');
var ranks=parseItems(c,'榜');
var h='<div class="ld"><div class="ld-hdr"><div class="ld-nm">'+esc(mn)+'</div><div class="ld-sub">';
var subs=[];
if(pfm)subs.push(pfm);
if(dt)subs.push(dt);
if(dur)subs.push('时长 '+dur);
h+=esc(subs.join(' · '));
h+='</div></div><div class="ld-cards">';
if(views)h+='<div class="ld-card"><div class="ld-cv">'+fmtNum(views)+'</div><div class="ld-cl">观看人次</div></div>';
if(peak)h+='<div class="ld-card"><div class="ld-cv">'+fmtNum(peak)+'</div><div class="ld-cl">最高在线</div></div>';
if(fans)h+='<div class="ld-card"><div class="ld-cv">'+fmtNum(fans)+'</div><div class="ld-cl">新增粉丝</div></div>';
if(tips)h+='<div class="ld-card"><div class="ld-cv">'+fmtMoney(tips)+'</div><div class="ld-cl">打赏总额</div></div>';
h+='</div>';
var hasBiz=gmv||avg||ret||comm;
if(hasBiz){
h+='<div class="ld-sec">带货数据</div><div class="ld-cards">';
if(gmv)h+='<div class="ld-card"><div class="ld-cv">'+fmtMoney(gmv)+'</div><div class="ld-cl">GMV</div></div>';
