if(comm)h+='<div class="ld-card"><div class="ld-cv">'+fmtMoney(comm)+'</div><div class="ld-cl">佣金收入</div></div>';
h+='</div>';
}
if(ranks.length>0){
h+='<div class="ld-rank"><div class="ld-rl">🏆 贡献榜</div>';
for(var i=0;i<ranks.length;i++){var r=ranks[i];
var rk=parseInt(r[0])||99;var rkCls=rk<=3?'top3':'normal';
h+='<div class="ld-ri"><span class="ld-rk '+rkCls+'">'+esc(r[0]||'')+'</span>';
h+='<span class="ld-run">'+esc(r[1]||'')+'</span>';
h+='<span class="ld-rgf">'+esc(r[2]||'')+'</span>';
if(r[3])h+='<span class="ld-ramt">'+fmtMoney(r[3])+'</span>';
h+='</div>';}
h+='</div>';
}
h+='</div>';
return h;
}
function rLiveRank(c){
var mn=pf(c,'主播')||'';
var pfm=pf(c,'平台')||'';
var period=pf(c,'周期')||'';
