h+='</div>';
if(r[3])h+='<span class="lr-amt">'+fmtMoney(r[3])+'</span>';
h+='</div>';}
h+='</div></div>';
return h;
}
function renderBlock(type,block){
switch(type){
case'live_stream':return rLiveStream(block);
case'short_video':return rShortVideo(block);
case'live_data':return rLiveData(block);
case'live_rank':return rLiveRank(block);
default:return'';
}
}
function init(){
try{
var msg=getMsg();
if(!msg){document.getElementById('live-ui-root').innerHTML='<div style="padding:10px;color:#f66">❌ 无法获取消息</div>';return;}
