function getMvuDataSafe() {
    const checkObj = (win) => {
        try {
            if (win.Mvu && typeof win.Mvu.getMvuData === 'function')
                return win.Mvu.getMvuData({ type: 'message', message_id: 'latest' })?.stat_data;
            if (win.mag_var_update && win.mag_var_update.data)
                return win.mag_var_update.data;
        } catch(e) { return null; }
    };
    return checkObj(window) || checkObj(window.parent) || checkObj(window.top);
}

const getVal = (data, path, def = '无') => {
    if (!data) return def;
    let current = data;
    try {
        const keys = path.split('.');
        for (const key of keys) {
            if (current === undefined || current === null) return def;
            current = current[key];
        }
        return (current !== undefined && current !== null && current !== '') ? current : def;
    } catch (e) { return def; }
};

const fmtMoney = (v) => {
    const n = Number(String(v).replace(/[^\d.-]/g, ''));
    if (!isFinite(n) || n === 0) return '0';
    const abs = Math.abs(n);
    if (abs >= 100000000) return (n / 100000000).toFixed(2).replace(/\.?0+$/, '') + '亿';
    if (abs >= 10000) return (n / 10000).toFixed(2).replace(/\.?0+$/, '') + '万';
    return n.toLocaleString('zh-CN');
};

const pickNum = (str) => {
    const m = String(str).match(/(\d+(?:\.\d+)?)/);
    return m ? Number(m[1]) : 0;
};

const renderModules = {
    home: (sd) => {
        const name = getVal(sd, '主角.姓名', '未知');
        const gender = getVal(sd, '主角.性别', '未知');
        const nation = getVal(sd, '主角.国籍', '未知');
        const age = getVal(sd, '主角.年龄', '0');
        const job = getVal(sd, '主角.职业', '无');
        const look = getVal(sd, '主角.外貌', '无');
        const health = getVal(sd, '主角.身体状态', '健康');
        const money = getVal(sd, '财务.钱财', 0);

        const rawLevel = String(getVal(sd, '专业评估.当前咖位', '素人'));
        const lvMatch = rawLevel.match(/^([^(（]+)[(（](.+)[)）]$/);
        const level = lvMatch ? lvMatch[1] : rawLevel;
        const levelNote = lvMatch ? lvMatch[2] : '';

        const ability = getVal(sd, '专业评估.业务能力', '无');
        const media = getVal(sd, '专业评估.媒体风向', '无');
        const publicRep = getVal(sd, '专业评估.社   风评', '无');
        const fans = getVal(sd, '专业评估.粉丝基础', '无');

        const receivables = getVal(sd, '财务.应收应付', {});
        const estates = getVal(sd, '财务.不动产', {});

        const isHealthy = String(health) === '健康';

        const infoList = [
            {k:'姓名', v:name, hl:true},
            {k:'性别', v:gender},
            {k:'国籍', v:nation},
            {k:'年龄', v:age + '岁'},
            {k:'职业', v:job},
            {k:'外貌', v:look},
            {k:'状态', v:health, cls: isHealthy ? '' : 'hl-danger', wrap:true},
            {k:'钱财', v:'¥ ' + fmtMoney(money), hl:true}
        ];

        const evalList = [
            {k:'业务能力', v:ability},
            {k:'媒体风向', v:media},
            {k:'社会风评', v:publicRep},
            {k:'粉丝基础', v:fans}
        ];

        const renderFinance = (obj) => {
            if (!obj || typeof obj !== 'object' || Object.keys(obj).length === 0) {
                return `<div style="font-size:12px; color:var(--c-sub); padding:4px;">暂无往来账目</div>`;
            }
            let sumIn = 0, sumOut = 0;
            Object.values(obj).forEach(v => {
                const s = String(v);
                if (s.indexOf('应付') === 0 || s.indexOf('应付') > -1 && s.indexOf('应收') === -1) sumOut += pickNum(s);
                else sumIn += pickNum(s);
            });

            const rows = Object.keys(obj).map(k => {
                const s = String(obj[k]);
                const isOut = s.indexOf('应付') > -1;
                const parts = s.split('/');
                const amt = parts[0] || '';
                const due = parts[1] || '';
                const src = parts.slice(2).join('/') || '';
                const amtNum = pickNum(amt);
                const label = isOut ? '应付' : '应收';
                return `
                    <div class="fin-row">
                        <div class="fin-head">
                            <span class="fin-name">${k}</span>
                            <span class="${isOut ? 'hl-danger' : 'hl-main'}" style="font-size:12px; font-weight:600;">${isOut?'-':'+'}${fmtMoney(amtNum)}</span>
                        </div>
                        <div class="fin-sub">${label}${due ? ' · ' + due : ''}${src ? ' · ' + src : ''}</div>
                    </div>
                `;
            }).join('');

            return `
                <div class="fin-total">
                    <span>应收 <b class="hl-main">${fmtMoney(sumIn)}</b></span>
                    <span>应付 <b class="hl-danger">${fmtMoney(sumOut)}</b></span>
                </div>
                ${rows}
            `;
        };

        const renderEstate = (obj) => {
            if (!obj || typeof obj !== 'object' || Object.keys(obj).length === 0) {
                return `<div style="font-size:12px; color:var(--c-sub); padding:4px;">暂无置产</div>`;
            }
            return Object.keys(obj).map(k => {
                const parts = String(obj[k]).split('/');
                const price = parts[0] || '';
                const date = parts[1] || '';
                const state = parts[2] || '';
                const risky = state.indexOf('抵押') > -1 || state.indexOf('待售') > -1;
                return `
                    <div class="fin-row">
                        <div class="fin-head">
                            <span class="fin-name">${k}</span>
                            <span class="hl-main" style="font-size:12px; font-weight:600;">${fmtMoney(price)}</span>
                        </div>
                        <div class="fin-sub">
                            ${date ? `<span class="mini-tag">${date}</span>` : ''}
                            ${state ? `<span class="mini-tag${risky ? ' mini-tag-warn' : ''}">${state}</span>` : ''}
                        </div>
                    </div>
                `;
            }).join('');
        };

        return `
            <div class="card-box">
                <div class="card-title">基本信息</div>
                ${infoList.map(i => `
                    <div class="info-item">
                        <span class="info-label">${i.k}</span>
                        <span class="info-val ${i.hl?'hl-main':''} ${i.cls||''}" ${i.wrap?'style="max-width:66%; white-space:normal; line-height:1.5;"':''}>${i.v}</span>
                    </div>
                `).join('')}
            </div>

            <div class="card-box">
                <div class="card-title">应收应付</div>
                ${renderFinance(receivables)}
            </div>

            <div class="card-box">
                <div class="card-title">不动产业</div>
                ${renderEstate(estates)}
            </div>

            <div class="card-box">
                <div class="card-title">专业评估</div>
                <div class="info-item">
                    <span class="info-label">当前咖位</span>
                    <span class="info-val hl-main" style="text-align:right;">
                        ${level}${levelNote ? `<div style="font-size:9px; color:var(--c-sub); font-weight:400; letter-spacing:0; margin-top:2px; text-shadow:none;">${levelNote}</div>` : ''}
                    </span>
                </div>
                ${evalList.map(i => `
                    <div class="info-item">
                        <span class="info-label">${i.k}</span>
                        <span class="info-val">${i.v}</span>
                    </div>
                `).join('')}
            </div>
        `;
    },
    works: (sd) => {
        const renderList = (title, obj) => {
            let content = '';
            if (!obj || typeof obj !== 'object' || Object.keys(obj).length === 0) {
                content = `<div style="font-size:12px; color:var(--c-sub); padding:4px;">暂无记录</div>`;
            } else {
                content = Object.keys(obj).map(k => `
                    <div class="info-item">
                        <span class="info-val" style="text-align:left; color:var(--c-text);">${k}</span>
                        <span class="info-label" style="font-size:12px;">${obj[k]}</span>
                    </div>
                `).join('');
            }
            return `<div class="card-box"><div class="card-title">${title}</div>${content}</div>`;
        };

        const movies = getVal(sd, '代表作品.影视作品', {});
        const musics = getVal(sd, '代表作品.音乐作品', {});
        const shows = getVal(sd, '代表作品.综艺作品', {});
        const ads = getVal(sd, '价值分析.广告代言', {});
        const awards = getVal(sd, '代表作品.获取奖项', {});

        return `
            ${renderList('影视作品', movies)}
            ${renderList('音乐作品', musics)}
            ${renderList('综艺作品', shows)}
            ${renderList('广告代言', ads)}
            ${renderList('荣誉记录', awards)}
        `;
    },
    social: (sd) => {
        const circles = getVal(sd, '人脉.社交版图', []);
        const lovers = getVal(sd, '人脉.情人', {});
        const relationMap = getVal(sd, '人脉.关系簿', {});
        const teamMap = getVal(sd, '人脉.团队', {});
        const aiTakeover = getVal(sd, '人脉.AI接管', {});

        const aiNames = (aiTakeover && typeof aiTakeover === 'object') ? Object.keys(aiTakeover) : [];

        const renderTags = (arr) => (arr && arr.length && arr[0]!=='无') ?
            `<div class="tag-container">${arr.map(i=>`<span class="tag">${i}</span>`).join('')}</div>` :
            '<div style="color:var(--c-sub); font-size:12px;">无</div>';

        const RELATION_MAP = [
            { re: /利益共同体|心腹/,            cls: 'rl-core'    },
            { re: /死敌|不共戴天|封杀/,          cls: 'rl-enemy'   },
            { re: /竞品|对家|旧怨|敌意/,         cls: 'rl-rival'   },
            { re: /盟友|师承|恩人|好感/,         cls: 'rl-ally'    },
            { re: /点头之交|泛泛|一般|合作/,      cls: 'rl-neutral' }
        ];

        const renderRelations = (obj) => {
            if (!obj || typeof obj !== 'object' || Object.keys(obj).length === 0) {
                return '<div style="font-size:12px; color:var(--c-sub);">暂无记录</div>';
            }
            return Object.keys(obj).map(k => {
                const isAI = aiNames.includes(k);
                const raw = String(obj[k]);
                const parts = raw.split('/');
                const role = parts.length > 1 ? parts[0] : '';
                const relRaw = (parts.length > 1 ? parts.slice(1).join('/') : raw).trim();
                const pm = relRaw.match(/^([^(（]+)[(（](.+)[)）]$/);
                const relMain = pm ? pm[1].trim() : relRaw;
                const relNote = pm ? pm[2].trim() : '';

                let cls = 'rl-tag rl-neutral';
                for (const m of RELATION_MAP) {
                    if (m.re.test(relRaw)) { cls = 'rl-tag ' + m.cls; break; }
                }

                return `
                    <div class="rel-row">
                        <div class="rel-head">
                            <span class="rel-name">${k}${isAI ? '<span class="ai-tag">AI</span>' : ''}</span>
                            <span class="${cls}">${relMain}</span>
