            return `<div class="card-box"><div class="card-title">${title}</div>${content}</div>`;
        };

        const renderArr = (arr) => {
            if (!arr || !arr.length || arr[0] === '无') {
                return '<div style="font-size:12px; color:var(--c-sub);">无</div>';
            }
            const CORE = /经纪约|全约|代理约|签约|合约/;
            const RISK = /对赌|竞业|违约|禁止|排他|保底|抵押/;
            const DUR = /(?:\d+(?:\+\d+)?年|至\d{4}[-.]?\d{0,2})/;

            return `<div class="tag-container">${arr.map(item => {
                const s = String(item);
                const parenIdx = s.search(/[（(]/);
                const head = parenIdx === -1 ? s : s.slice(0, parenIdx);
                const tail = parenIdx === -1 ? '' : s.slice(parenIdx);

                const durMatch = head.match(DUR);
                const dur = durMatch ? durMatch[0] : '';
                const name = ((dur ? head.replace(dur, '') : head).trim()) + tail;

                let cls = 'ct-tag';
                if (RISK.test(s)) cls += ' ct-risk';
                else if (CORE.test(s)) cls += ' ct-core';

                return `<span class="${cls}">${name}${dur ? `<i class="ct-dur">${dur}</i>` : ''}</span>`;
