                <div class="news-block">${n2}</div>
            </div>

            <div class="card-box">
                <div class="card-title">备忘录</div>
                ${renderMemos(memos)}
            </div>

            <div class="card-box">
                <div class="card-title">价值分析</div>
                <div class="info-item">
                    <span class="info-label">签约公司</span>
                    <span class="info-val hl-main">${company}</span>
                </div>
                <div style="margin-top:8px; padding-top:8px; border-top:1px dashed var(--c-border);">
                    <div style="font-size:10px; color:var(--c-sub); margin-bottom:4px; letter-spacing:1px;">合约状态</div>
                    ${renderArr(contracts)}
                </div>
            </div>

            ${renderList('投资项目', invests)}
        `;
    }
};

function destroyFatePhone() {
    if (window.fateAudioInstance) {
        window.fateAudioInstance.pause();
        window.fateAudioInstance.src = '';
        delete window.fateAudioInstance;
    }
    $('#fate-phone-container, #fate-phone-css, #fate-drag-overlay').remove();
    $(document).off('.fatephone');
    $(window).off('.fatephone');
}

function initFatePhone() {
    $('head').append(fateStyles);
    $('body').prepend(fateTemplate);
    const container = $('#fate-phone-container');
    const overlay = $('#fate-drag-overlay');
    const content = $('#fp-content');

    container.css({ top: '80px', left: '10px' });

    const render = () => {
        const sd = getMvuDataSafe() || {};

        $('#fp-title').text(getVal(sd, '叙事.标题', '逐梦网络'));
        $('#fp-quote').text(getVal(sd, '叙事.引言', '...'));

        const bgmBtn = $('#btn-bgm');
        bgmBtn.text(fateState.isBgmOn ? '🔊' : '🔇');
        bgmBtn.css('opacity', fateState.isBgmOn ? '1' : '0.45');

        if (fateState.isCollapsed) container.addClass('collapsed');
        else container.removeClass('collapsed');

        const renderer = renderModules[fateState.currentTab] || renderModules.home;
        content.html(renderer(sd));

        $('.nav-btn').removeClass('active');
        $(`.nav-btn[data-tab="${fateState.currentTab}"]`).addClass('active');
    };

    container.on('click.fatephone', '.nav-btn', function(e) {
        e.stopPropagation();
        fateState.currentTab = $(this).data('tab');
        render();
    });

    const toggleCollapse = (e) => {
        if (container.data('isDragging')) return;
        if(e && e.stopPropagation) e.stopPropagation();

        fateState.isCollapsed = !fateState.isCollapsed;
        localStorage.setItem(window.FATE_CONFIG.storageCollapse, fateState.isCollapsed);
        render();
    };
    container.on('click.fatephone', '#btn-fold', toggleCollapse);

    const audio = window.fateAudioInstance;
    $(document).one('click', function() { if (fateState.isBgmOn && audio.paused) audio.play(); });

    container.on('click.fatephone', '#btn-bgm', function(e) {
        e.stopPropagation();
        fateState.isBgmOn = !fateState.isBgmOn;
        render();
        if (fateState.isBgmOn) audio.play().catch(()=>{});
        else audio.pause();
    });

    let dragStartX, dragStartY;
    let initialLeft, initialTop;
    let dragStartTarget = null;

    container.on('mousedown.fatephone touchstart.fatephone', '.fate-drag-handle', function(e) {
        if (e.target.closest('.ctrl-btn')) return;

        container.data('isDragging', false);

        const evt = e.type === 'touchstart' ? e.originalEvent.touches[0] : e;
        dragStartX = evt.clientX;
        dragStartY = evt.clientY;
        dragStartTarget = e.target;

        const rect = container[0].getBoundingClientRect();
        initialLeft = rect.left;
        initialTop = rect.top;

        overlay.show();

        if(e.type === 'mousedown') e.preventDefault();
    });

    overlay.on('mousemove.fatephone touchmove.fatephone', function(e) {
        const moveEvt = e.type === 'touchmove' ? e.originalEvent.touches[0] : e;
        const deltaX = moveEvt.clientX - dragStartX;
        const deltaY = moveEvt.clientY - dragStartY;

        if (Math.abs(deltaX) > 2 || Math.abs(deltaY) > 2) {
            container.data('isDragging', true);
            container.css({
                left: (initialLeft + deltaX) + 'px',
                top: (initialTop + deltaY) + 'px',
                right: 'auto',
                bottom: 'auto'
            });
        }
        if(e.type === 'touchmove') e.preventDefault();
    });

    overlay.on('mouseup.fatephone touchend.fatephone', function(e) {
        overlay.hide();

        if (container.data('isDragging')) {
            setTimeout(() => container.data('isDragging', false), 50);
        }
        else {
            if (dragStartTarget && $(dragStartTarget).closest('.collapsed-icon').length) {
                toggleCollapse(e);
            }
        }

        dragStartTarget = null;
    });

    container.on('dblclick.fatephone', '.header-info', function() {
        const resetPos = { top: '80px', left: '10px' };
        container.css(resetPos);
    });

    let isDown = false, startY, scrollTop;
    content.on('mousedown.fatephone', e => {
        if ($(e.target).closest('.fate-drag-handle').length) return;
        isDown = true; startY = e.pageY - content.offset().top; scrollTop = content.scrollTop();
    });
    content.on('mouseleave.fatephone mouseup.fatephone', () => { isDown = false; });
    content.on('mousemove.fatephone', e => { if(isDown) { e.preventDefault(); content.scrollTop(scrollTop - (e.pageY - content.offset().top - startY) * 1.5); } });
    content.on('touchstart.fatephone', e => {
        if ($(e.target).closest('.fate-drag-handle').length) return;
        isDown = true; startY = e.originalEvent.touches[0].pageY - content.offset().top; scrollTop = content.scrollTop();
    });
    content.on('touchend.fatephone', () => { isDown = false; });
    content.on('touchmove.fatephone', e => { if(isDown) { content.scrollTop(scrollTop - (e.originalEvent.touches[0].pageY - content.offset().top - startY) * 1.5); } });

    render();

    let initCount = 0;
    const initInterval = setInterval(() => {
        const sd = getMvuDataSafe();
        if (sd && Object.keys(sd).length > 0) {
            render();
            clearInterval(initInterval);
            return;
        }
        render();
        initCount++;
        if (initCount > 14) clearInterval(initInterval);
    }, 500);

    let updateTimer = null;
    const debouncedUpdate = () => { if (updateTimer) clearTimeout(updateTimer); updateTimer = setTimeout(() => { render(); updateTimer = null; }, 500); };

    const chatChangedHandler = () => {
        setTimeout(() => {
            const sd = getMvuDataSafe();
            if (!sd || Object.keys(sd).length === 0) {
                destroyFatePhone();
            }
        }, 300);
    };

    if (typeof eventOn !== 'undefined') {
        if (window.tavern_events) eventOn(tavern_events.MESSAGE_RECEIVED, debouncedUpdate);
        if (window.Mvu && Mvu.events) eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, debouncedUpdate);
        try { if(window.parent && window.parent.eventOn && window.parent.Mvu) window.parent.eventOn(window.parent.Mvu.events.VARIABLE_UPDATE_ENDED, debouncedUpdate); } catch(e) {}

        if (window.tavern_events && window.tavern_events.CHAT_ID_CHANGED) {
            eventOn(tavern_events.CHAT_ID_CHANGED, chatChangedHandler);
        }
    }

    if (window.eventSource) {
        eventSource.on('chat_id_changed', chatChangedHandler);
    }
}

const checkReady = setInterval(() => { if (window.jQuery) { clearInterval(checkReady); initFatePhone(); } }, 200);
$(window).on('pagehide.fatephone unload.fatephone', destroyFatePhone);

