    '👑 资本篇': [条.资方, 条.院线, 条.卫视, 条.网剧, 条.潜规则, 条.营销, 条.狗仔],
    '🔄 全开模式': [...触发层],
    '🧹 日常模式': [条.饭圈, 条.狗仔],
  };

  const 提示头 = '场景切换';
  const 主名 = 值 => String(值 ?? '').split('[')[0].trim();
  const 取名称 = 条目 => 条目.comment ?? 条目.name ?? '';
  const 有函数 = 名 => typeof window[名] === 'function';

  if (!有函数('toastr') && typeof toastr === 'undefined') {
    console.error('[场景切换] 未找到 toastr，脚本终止');
    return;
  }

  const 按钮依赖 = ['appendInexistentScriptButtons', 'getButtonEvent', 'eventOn'];
  const 缺失依赖 = 按钮依赖.filter(名 => !有函数(名));
  if (缺失依赖.length > 0) {
    toastr.error(
      `酒馆助手版本过低，缺少接口：${缺失依赖.join('、')}。请升级后重试`,
      提示头,
      { timeOut: 10000 }
    );
