  }

  let 读条目, 写条目, 是新版;
  if (有函数('getWorldbook') && 有函数('replaceWorldbook')) {
    读条目 = getWorldbook;
    写条目 = replaceWorldbook;
    是新版 = true;
  } else if (有函数('getLorebookEntries') && 有函数('setLorebookEntries')) {
    读条目 = getLorebookEntries;
    写条目 = setLorebookEntries;
    是新版 = false;
  } else {
    toastr.error('未找到世界书读写接口，请升级酒馆助手版本', 提示头, { timeOut: 10000 });
