  }

  const 列书名 = 有函数('getWorldbookNames')
    ? getWorldbookNames
    : 有函数('getLorebookNames')
      ? getLorebookNames
      : null;

  let 世界书名 = 配置.默认世界书名;
  if (列书名) {
    try {
      const 全部书名 = await 列书名();
      if (Array.isArray(全部书名)) {
        const 命中 = 全部书名.filter(名 => String(名).startsWith(配置.世界书名前缀));
        if (命中.length === 1) {
          世界书名 = 命中[0];
        } else if (命中.length > 1) {
          世界书名 = 命中.includes(配置.默认世界书名) ? 配置.默认世界书名 : [...命中].sort().pop();
          toastr.warning(
            `匹配到多本世界书：${命中.join('、')}，已使用《${世界书名}》`,
