  if (重名.length > 0) {
    toastr.warning(`以下主名存在重复条目，将被同时开关：${重名.join('、')}`, 提示头, { timeOut: 10000 });
  }

  let 忙 = false;

  async function 切换场景(预设名) {
    if (忙) {
      toastr.warning('上一次切换还没完成，请稍候', 提示头);
      return;
    }
    忙 = true;
    try {
      const 启用集 = new Set((预设[预设名] ?? []).map(主名));
      const 条目们 = await 读条目(世界书名);
      if (!Array.isArray(条目们) || 条目们.length === 0) {
        toastr.error(`读取《${世界书名}》失败或世界书为空`, 提示头, { timeOut: 8000 });
        return;
      }

      const 变更 = [];
      const 更新后 = 条目们.map(条目 => {
        const 名 = 主名(取名称(条目));
        if (!触发集.has(名)) return 条目;
        const 目标 = 启用集.has(名);
        if (条目.enabled === 目标) return 条目;
        const 新条目 = { ...条目, enabled: 目标 };
        变更.push(新条目);
        return 新条目;
      });

      if (变更.length === 0) {
        toastr.info(`已经处于【${预设名}】，无需切换`, 提示头);
        return;
      }

      if (是新版) {
        await 写条目(世界书名, 更新后, { render: 'immediate' });
      } else {
        await 写条目(世界书名, 变更.map(条目 => ({ uid: 条目.uid, enabled: 条目.enabled })));
      }

      const 当前启用 = 更新后
        .filter(条目 => 条目.enabled && 触发集.has(主名(取名称(条目))))
        .map(条目 => 主名(取名称(条目)));

      if (配置.调试验证) {
        const 验证条目 = await 读条目(世界书名);
        const 验证启用 = new Set(
          (Array.isArray(验证条目) ? 验证条目 : [])
            .filter(条目 => 条目.enabled)
            .map(条目 => 主名(取名称(条目)))
        );
        const 漏启用 = [...启用集].filter(名 => 主名计数.has(名) && !验证启用.has(名));
        if (漏启用.length > 0) {
          toastr.error(
            `以下条目写入后未生效：${漏启用.join('、')}。可能是版本字段差异，请反馈给制卡者`,
            提示头,
            { timeOut: 12000 }
          );
          return;
        }
      }

      toastr.success(
        当前启用.length > 0
          ? `【${预设名}】已生效，启用 ${当前启用.length} 项：${[...new Set(当前启用)].join('、')}`
          : `【${预设名}】触发层已全部休眠`,
        提示头,
        { timeOut: 6000 }
      );
    } catch (错误) {
      toastr.error('切换失败，详见控制台(F12)', 提示头, { timeOut: 8000 });
      console.error('[场景切换] 切换异常:', 错误);
    } finally {
      忙 = false;
    }
  }

  async function 显示状态() {
    try {
      const 条目们 = await 读条目(世界书名);
      if (!Array.isArray(条目们)) {
        toastr.error(`读取《${世界书名}》失败`, 提示头, { timeOut: 8000 });
        return;
      }
      const 启用中 = new Set(
        条目们
          .filter(条目 => 条目.enabled && 触发集.has(主名(取名称(条目))))
          .map(条目 => 主名(取名称(条目)))
      );
      const 命中预设 = Object.entries(预设).find(([, 表]) => {
        const 目标 = new Set(表.map(主名).filter(名 => 主名计数.has(名)));
        return 目标.size === 启用中.size && [...目标].every(名 => 启用中.has(名));
      });
      toastr.info(
        `${命中预设 ? `【${命中预设[0]}】` : '自定义组合'}\n${[...启用中].join('、') || '触发层全部休眠'}`,
        提示头,
        { timeOut: 8000 }
      );
    } catch (错误) {
      toastr.error('读取世界书失败，详见控制台(F12)', 提示头, { timeOut: 8000 });
      console.error('[场景切换] 状态读取异常:', 错误);
    }
  }

  const 监听表 = [];
  function 绑按钮(按钮名, 回调) {
    const 事件 = getButtonEvent(按钮名);
    eventOn(事件, 回调);
    监听表.push([事件, 回调]);
  }

  const 预设名们 = Object.keys(预设);
  appendInexistentScriptButtons(
    [...预设名们, 配置.状态按钮名].map(名 => ({ name: 名, visible: true }))
  );
  预设名们.forEach(名 => 绑按钮(名, () => 切换场景(名)));
  绑按钮(配置.状态按钮名, 显示状态);

  $(window)
    .off('pagehide.场景切换')
    .on('pagehide.场景切换', () => {
      if (有函数('eventRemoveListener')) {
        监听表.forEach(([事件, 回调]) => eventRemoveListener(事件, 回调));
      }
      监听表.length = 0;
    });

  toastr.info(
    `场景切换已就绪（${世界书名}），按钮在输入区魔法棒菜单`,
    提示头,
    { timeOut: 5000 }
  );
})();

